package org.racedaydreams.domain.presentation;
import java.time.*;
import java.util.*;
import org.racedaydreams.domain.*;
import org.racedaydreams.domain.activity.*;
import org.racedaydreams.domain.baseline.*;
import org.racedaydreams.domain.body.*;
import org.racedaydreams.domain.coaching.*;
import org.racedaydreams.domain.strength.*;

public final class RefinementTestSuite {
    static int checks;static final LocalDate DAY=LocalDate.of(2026,10,19);static final Instant NOW=DAY.atStartOfDay().toInstant(ZoneOffset.UTC);
    static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
    public static void main(String[] args){calendar();weights();strength();performance();review();durability();System.out.println("RefinementTestSuite: "+checks+" checks passed (calendar, graph, unified PB, performance evidence, review presentation).");}
    static UserProfile profile(){return new UserProfile(new RaceGoal(RaceDistance.TEN_K,"Race",DAY.plusWeeks(8),GoalMode.TARGET_TIME,Duration.ofMinutes(55)),new TrainingPreferences(TrainingStrategy.BALANCED,EnumSet.of(DayOfWeek.MONDAY,DayOfWeek.TUESDAY,DayOfWeek.THURSDAY,DayOfWeek.SATURDAY),3,DayOfWeek.SATURDAY,Set.of(DayOfWeek.MONDAY),ScheduleType.FIXED,UnitSystem.METRIC),false);}
    static PlannedWorkout w(String id,LocalDate date,WorkoutCategory type){return new PlannedWorkout(id,date,type,5.0,null,List.of(),"");}
    static PlanVersion plan(List<PlannedWorkout> ws){return new PlanVersion("v","p",1,NOW,"Original",profile(),"Evidence",new TrainingPlan("p",DAY,DAY.plusWeeks(8),List.of(),ws));}
    static ActivityRecord run(String id,LocalDate day,String planned){return new ActivityRecord(id,new SourceIdentity("manual",id,null),day.atTime(8,0).toInstant(ZoneOffset.UTC),day.atTime(9,0).toInstant(ZoneOffset.UTC),ZoneOffset.UTC,ZoneOffset.UTC,5000.0,null,null,null,null,null,3.0,"",List.of(),List.of(),planned,null);}
    static StrengthSession gym(String id,LocalDate date,double kg){return new StrengthSession(id,date.atTime(18,0).toInstant(ZoneOffset.UTC),ZoneOffset.UTC,Duration.ofMinutes(45),7.0,"Note",List.of(new StrengthSession.ExerciseSets(StrengthExercise.starters().get(0),List.of(new StrengthSession.SetEntry(id+"set",5,kg,7.0,false)))));}
    static void calendar(){
        var types=Map.of(WorkoutCategory.EASY_RUN,CalendarData.Category.EASY,WorkoutCategory.TEMPO_THRESHOLD_RUN,CalendarData.Category.QUALITY,WorkoutCategory.LONG_RUN,CalendarData.Category.LONG,WorkoutCategory.RACE,CalendarData.Category.RACE);
        for(var t:types.entrySet()){var ws=List.of(w("w",DAY,t.getKey()));var v=plan(ws);var entries=CalendarData.day(DAY,DAY,v,ws,List.of(),List.of(),Map.of(),List.of());check(entries.get(0).category()==t.getValue(),"Meaningful category");check(entries.get(0).state()==CalendarData.State.PLANNED,"Planned state");check(!entries.get(0).description().contains("_"),"Readable accessibility description");var done=CalendarData.day(DAY,DAY,v,ws,List.of(run("a",DAY,"w")),List.of(gym("s",DAY,80)),Map.of(),List.of());check(done.size()==2,"Run and gym retained without duplicate planned entries");check(done.stream().allMatch(e->e.state()==CalendarData.State.COMPLETED),"Completion independent of category");check(done.get(1).category()==CalendarData.Category.STRENGTH,"Strength marker");}
        var v=plan(List.of(w("w",DAY,WorkoutCategory.EASY_RUN)));
        check(CalendarData.day(DAY.plusDays(1),DAY,v,v.plan().workouts(),List.of(),List.of(),Map.of(),List.of()).get(0).category()==CalendarData.Category.REST,"Unassigned available plan day is planned rest");
        check(CalendarData.day(DAY.plusDays(2),DAY,v,v.plan().workouts(),List.of(),List.of(),Map.of(),List.of()).isEmpty(),"Unavailable date is not labelled rest");
        check(CalendarData.day(DAY.minusWeeks(1),DAY,v,v.plan().workouts(),List.of(),List.of(),Map.of(),List.of()).isEmpty(),"Outside programme not false rest");
        check(CalendarData.day(DAY,DAY,null,List.of(),List.of(),List.of(),Map.of(),List.of()).isEmpty(),"No plan blank is not rest");
        for(var kind:WorkoutDecision.Kind.values()){var d=new WorkoutDecision("d","w","v",DAY,kind==WorkoutDecision.Kind.MOVED?DAY.plusDays(1):null,kind,NOW);var es=CalendarData.day(DAY,DAY,v,List.of(),List.of(),List.of(),Map.of(),List.of(d));check(es.stream().anyMatch(e->e.state()==(kind==WorkoutDecision.Kind.MOVED?CalendarData.State.MOVED:CalendarData.State.SKIPPED)),"Explicit choice labelled");check(es.stream().noneMatch(e->e.category()==CalendarData.Category.REST),"Moved/skipped is not rest");}
        check(CalendarData.outsideMonth(DAY.minusMonths(1),DAY),"Outside-month styling");check(!CalendarData.outsideMonth(DAY.plusDays(1),DAY),"Same month styling");
        check(CalendarData.day(DAY,DAY.plusDays(1),v,v.plan().workouts(),List.of(),List.of(),Map.of(),List.of()).get(0).state()==CalendarData.State.NOT_COMPLETED,"Past unrecorded neutral state");
    }
    static BodyWeight weight(String id,int days,double kg){return new BodyWeight(id,kg,NOW.minus(Duration.ofDays(days)),ZoneOffset.UTC,"manual",id,null);}
    static void weights(){var data=List.of(weight("old",500,80),weight("year",200,79),weight("quarter",60,78),weight("month",15,77),weight("week",3,76),weight("today",0,75));int count=2;for(var range:List.of("Week","Month","3 Months","Year","All")){var g=WeightGraphData.of(data,DAY,range,MassUnit.KG);check(g.points().size()==count++,"Range filters genuine measurements");check(g.minimum()<g.maximum(),"Usable y axis");check(g.nearest(1).id().equals("today"),"Point selection identifies stored record");check(g.points().stream().allMatch(data::contains),"No fabricated measurements");}
        var lb=WeightGraphData.of(List.of(weight("a",0,75)),DAY,"Week",MassUnit.LB);check(Math.abs(lb.unit().fromKilograms(75)-165.3467)<.01,"Unit conversion");check(lb.x(0)==.5,"Sparse point centered");check(WeightGraphData.of(List.of(),DAY,"All",MassUnit.KG).nearest(.5)==null,"Empty selection");var same=WeightGraphData.of(List.of(weight("a",0,75),weight("b",0,76)),DAY,"All",MassUnit.KG);check(same.points().size()==2&&Double.isFinite(same.x(1)),"Same timestamp entries retained");
    }
    static void strength(){var e=StrengthExercise.starters().get(0);var manual=List.of(new HistoricalStrengthRecord("old",e,100,5,DAY.minusMonths(4),HistoricalStrengthRecord.DatePrecision.EXACT,""),new HistoricalStrengthRecord("around",e,105,5,DAY.minusMonths(2),HistoricalStrengthRecord.DatePrecision.APPROXIMATE,""),new HistoricalStrengthRecord("unknown",e,90,5,null,HistoricalStrengthRecord.DatePrecision.UNKNOWN,""));var sessions=List.of(gym("s1",DAY.minusDays(10),108),gym("s2",DAY,110));var all=StrengthProgression.timeline(sessions,manual);var history=all.stream().filter(p->p.category().equals("Load × 5")).toList();check(history.size()==5,"Unified manual and observed history");check(history.get(0).id().equals("old"),"Known dates chronological");check(history.get(history.size()-1).date()==null,"Unknown date not fake ordered");check(history.stream().anyMatch(p->p.precision()==HistoricalStrengthRecord.DatePrecision.APPROXIMATE),"Approximate precision retained");check(history.stream().anyMatch(p->p.provenance().equals("Historical/manual PB")),"Manual provenance");check(history.stream().anyMatch(p->p.sessionId()!=null),"Recorded source link");check(StrengthProgression.best(all,e.id(),"Load × 5").kilograms()==110,"Observed exceeds historical");check(StrengthProgression.best(StrengthProgression.timeline(List.of(),manual),e.id(),"Load × 5").kilograms()==105,"Deletion recalculates current best");check(StrengthProgression.best(StrengthProgression.timeline(sessions,List.of()),e.id(),"Load × 5").kilograms()==110,"Historical deletion derived only");}
    static RecordedResult result(String id,int days,int seconds,ResultSource source){return new RecordedResult(id,PerformanceDistance.FIVE_K,Duration.ofSeconds(seconds),DAY.minusDays(days),"Race",source,source==ResultSource.ROLLING?id:null,"");}
    static PerformanceReassessment.Review perf(List<RecordedResult> rs,BaselineConfidence b,int responses,boolean hard){return PerformanceReassessment.review(rs,List.of(),DAY,b,1,responses,hard);}
    static void performance(){var old=result("old",60,1800,ResultSource.OFFICIAL_CHIP);var big=result("big",3,1620,ResultSource.OFFICIAL_CHIP);
        check(!perf(List.of(old,result("small",3,1780,ResultSource.OFFICIAL_CHIP)),BaselineConfidence.STRONG,4,false).propose(),"Small gain no overreaction");
        var strong=perf(List.of(old,big),BaselineConfidence.STRONG,4,false);check(strong.propose()&&strong.confidence()==PerformanceReassessment.Confidence.STRONG,"Official plus corroboration");check(strong.fasterFraction()<=.03,"Bounded quality pace change");
        check(!perf(List.of(big),BaselineConfidence.STRONG,4,false).propose(),"One isolated result no prior comparison");check(!perf(List.of(old,big),BaselineConfidence.LOW,4,false).propose(),"Low baseline confidence");check(!perf(List.of(old,big),BaselineConfidence.STRONG,0,false).propose(),"Missing response evidence");check(!perf(List.of(old,big),BaselineConfidence.STRONG,4,true).propose(),"High RPE blocks pace increase");
        check(!perf(List.of(old,result("rolling",3,1600,ResultSource.ROLLING)),BaselineConfidence.STRONG,4,false).propose(),"Single rolling result limited");
        check(perf(List.of(old,result("manual",3,1600,ResultSource.MANUAL)),BaselineConfidence.MODERATE,4,false).confidence()==PerformanceReassessment.Confidence.MODERATE,"Manual provenance moderate");
        var rs=List.of(old,result("m1",10,1740,ResultSource.MANUAL),result("m2",3,1700,ResultSource.MANUAL));check(perf(rs,BaselineConfidence.STRONG,4,false).propose(),"Multiple corroborating performances");
        var a=new AssessmentResult("assessment",new BaselineAssessment(5,AssessmentMode.BEST_EFFORT),Duration.ofMinutes(26),9.0,NOW.minus(Duration.ofDays(3)),null);check(PerformanceReassessment.review(List.of(old),List.of(a),DAY,BaselineConfidence.STRONG,1,4,false).propose(),"Deliberate assessment evidence");
        var controlled=new AssessmentResult("controlled",new BaselineAssessment(5,AssessmentMode.CONTROLLED),Duration.ofMinutes(26),4.0,NOW.minus(Duration.ofDays(3)),null);check(!PerformanceReassessment.review(List.of(old),List.of(controlled),DAY,BaselineConfidence.STRONG,1,4,false).propose(),"Controlled assessment not claimed as race effort");
        check(!PerformanceReassessment.review(List.of(old,big),List.of(),DAY,BaselineConfidence.STRONG,.5,4,false).propose(),"Poor completion prevents pace review");
    }
    static void review(){var r=new WeeklyCoaching.Review("r","v",DAY,3,3,25,1,12.0,List.of("Observation"),List.of(new WeeklyCoaching.Channel("Consistency",WeeklyCoaching.State.STABLE,"Good"),new WeeklyCoaching.Channel("Effort",WeeklyCoaching.State.NEEDS_ATTENTION,"Review")),"No adjustment required",List.of(new WeeklyCoaching.Choice("keep","Keep original",List.of())));var p=WeeklyReviewData.of(r);check(p.noChange(),"Intentional no-change presentation");check(p.positives().size()==1&&p.attention().size()==1,"Evidence grouped without changing outcome");check(p.recommendation().equals(r.recommendation()),"Recommendation preserved");}
    static void durability(){var d=DurabilityData.of(run("a",DAY,null));check(d.firstHalfSecondsPerKm()==null,"Missing samples never generate halves");check(d.status().equals("Insufficient detailed run data"),"Clear missing-data state");}
}
